const items = $input.all();
const results = [];

for (const item of items) {
  const raw = item.json;
  const url = (raw.link || raw.guid || '').trim();
  const title = (raw.title || 'Sans titre').trim();
  const rawContent = (raw['content:encoded'] || raw.content || raw.contentSnippet || raw.description || '')
    .replace(/<[^>]+>/g, '').trim().substring(0, 800);
  const publishedAt = raw.isoDate || raw.pubDate || new Date().toISOString();
  const source = raw._source || 'Unknown';

  if (!url.startsWith('http') || !title) continue;

  // Summarize via Ollama (local, no external dependency)
  let summary = '';
  try {
    const prompt = 'Résume cette actualité tech en 2 phrases courtes en français. Sois factuel et neutre.\n\nTitre: ' + title + '\n\nContenu: ' + rawContent.substring(0, 400) + '\n\nRésumé:';
    const resp = await $httpRequest({
      method: 'POST',
      url: 'http://ollama:11434/api/generate',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'llama3.2:3b', prompt, stream: false })
    });
    summary = ((resp.response || '')).trim().substring(0, 500);
  } catch(e) {
    summary = rawContent.substring(0, 200);
  }

  results.push({
    json: {
      url,
      title,
      source,
      raw_content: rawContent.substring(0, 2000),
      summary: summary || rawContent.substring(0, 200),
      published_at: publishedAt,
      topics: '[]'
    }
  });
}

return results;

const stories = $input.all().map(item => item.json);
const users = $('Aggregate Users').first().json.users;

if (!stories.length) {
  return [{ json: { log: 'Aucune story à envoyer.' } }];
}

const emails = [];
const today = new Date().toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const esc = s => (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = s => esc(s).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const safeUrl = u => { try { const p = new URL(u); if (p.protocol !== 'http:' && p.protocol !== 'https:') return '#'; return escAttr(u); } catch(e) { return '#'; } };

for (const user of users) {
  if (!user.email) continue;

  const interests = (user.interests || []).map(i => String(i).toLowerCase().trim());

  let relevant = stories;
  if (interests.length > 0) {
    relevant = stories.filter(story => {
      const haystack = ((story.title || '') + ' ' + (story.summary || '')).toLowerCase();
      return interests.some(interest => haystack.includes(interest));
    });
    if (relevant.length === 0) relevant = stories.slice(0, 5);
  }

  relevant = relevant.slice(0, 10);

  const unsubUrl = 'http://localhost:5678/webhook/unsubscribe?token=' + user.unsubscribe_token;

  const storiesList = relevant.map((s, i) =>
    (i + 1) + '. ' + s.title + '\n   Source : ' + s.source + ' | ' + new Date(s.published_at).toLocaleDateString('fr-FR') + '\n   Lien : ' + s.url + '\n   ' + (s.summary || '(résumé indisponible)') + '\n'
  ).join('\n');

  const storiesHtml = relevant.map(s =>
    '<div style="margin:0 0 20px 0;padding:0 0 20px 0;border-bottom:1px solid #eee">' +
    '<p style="margin:0 0 4px 0;font-weight:bold;font-size:15px"><a href="' + safeUrl(s.url) + '" style="color:#1e40af;text-decoration:none">' + esc(s.title) + '</a></p>' +
    '<p style="margin:0 0 8px 0;color:#888;font-size:12px">' + esc(s.source) + ' &mdash; ' + new Date(s.published_at).toLocaleDateString('fr-FR') + '</p>' +
    '<p style="margin:0;font-size:14px;line-height:1.6;color:#333">' + esc(s.summary || '') + '</p>' +
    '</div>'
  ).join('');

  const htmlBody =
    '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
    '<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f9fafb">' +
    '<table width="100%" cellpadding="0" cellspacing="0"><tr><td>' +
    '<table width="600" align="center" cellpadding="0" cellspacing="0" style="margin:20px auto;background:#fff;border-radius:8px;overflow:hidden;border:1px solid #e5e7eb">' +
    '<tr><td style="background:#1e40af;padding:20px 24px">' +
    '<h1 style="margin:0;color:#fff;font-size:20px;font-weight:bold">Persona Newsletter</h1>' +
    '<p style="margin:4px 0 0;color:#93c5fd;font-size:13px">' + today + '</p>' +
    '</td></tr>' +
    '<tr><td style="padding:24px">' +
    '<p style="margin:0 0 8px">Bonjour <strong>' + esc(user.pseudo) + '</strong>,</p>' +
    '<p style="margin:0 0 24px;color:#6b7280;font-size:13px">' + relevant.length + ' article(s) — int&eacute;r&ecirc;ts : <em>' + esc(interests.join(', ') || 'tous') + '</em></p>' +
    storiesHtml +
    '<p style="margin:20px 0 0;font-size:12px;color:#9ca3af;border-top:1px solid #eee;padding-top:16px">' +
    'Persona &mdash; Agr&eacute;gateur IA &middot; 100% local &nbsp;&bull;&nbsp;' +
    '<a href="' + safeUrl(unsubUrl) + '" style="color:#9ca3af">Se d&eacute;sinscrire</a>' +
    '</p></td></tr></table></td></tr></table></body></html>';

  emails.push({
    json: {
      to: user.email,
      userId: user.id,
      pseudo: user.pseudo,
      subject: 'Persona Newsletter — ' + today,
      body: 'Bonjour ' + user.pseudo + ',\n\nVos actualités tech du ' + today + ' (' + relevant.length + ' articles) :\n\n' + storiesList + '\n---\nSe désinscrire : ' + unsubUrl + '\n\nPersona — Agrégateur IA · 100% local',
      htmlBody,
      storyCount: relevant.length
    }
  });
}

return emails.length > 0 ? emails : [{ json: { log: 'Aucun email à envoyer (0 users éligibles).' } }];
